    "type": "judge",
    "stem": "大革命时期，毛泽东以马克思列宁主义为指导，深入实际调查研究，在《中国社会各阶层的分析》《湖南农民运动考察报告》等著作中，提出了关于新民主主义革命的基本思想，标志着毛泽东思想开始萌芽。",
