      "C": "工业和农业的关系、沿海和内地的关系、中央和地方的关系、国家集体和个人的关系、国防建设经济建设、党和非党关系、汉族和少数民族的关系、革命和反革命的关系、是非关系、中国和外国的关系，都是围绕着一个基本方针，就是要把国内外一切积极因素调动起来，为资本主义事业服务",
      "D": "《论十大关系》中谈到的十大关系，即：工业和农业的关系、沿海和内地的关系、中央和地方的关系、国家集体和个人的关系、国防建设经济建设、党和非党关系、汉族和少数民族的关系、革命和反革命的关系、是非关系、中国和外国的关系，都是围绕着一个基本方针，就是要把国内外一切积极因素调动起来，为资本主义事业服务。“十大关系”前五条主要讨论经济问题，着眼于调动经济领域各个方面的积极因素；后五条论述的是政治生活和思想文化生活领域如何调动各种积极因素的问题"
