      "C": "1956年9月中共八大召开，提出国内的主要矛盾已经是人民对于建立先进的工业国的要求同落后的农业国的现实之间的矛盾，已经是人民对于经济文化迅速发展的需要同当前经济文化不能满足人民需要的状况之间的矛盾；提出我们的根本任务已经由解放生产力变为在新的生产关系下面保护和发展生产力；提出全国人民的主要任务是集中力量发展社会生产力，实现国家工业化、逐步满足人民日益增长的物质和文化需要；提出要把党和国家的工作重点转到技术革命和社会主义建设上来。毛泽东在中共八大做《关于修改党的章程的报告》，提出加强党的群众路线，健全党内民主集中制度建设，坚持集体领导，反对个人崇拜",
