      "B": "在全党和全国工作重心由革命转向建设的时候，面临着一个如何认识和处理社会主义社会矛盾的问题。1957年2月邓小平在扩大的最高国务会议上发表《关于正确处理人民内部矛盾的问题》的重要讲话，提出了社会主义社会两类不同性质矛盾的理论。(1)社会主义社会存在着敌我矛盾和人民内部矛盾两类不同性质的矛盾。(2)人民内部的矛盾，是在人民利益根本一致的基础上的矛盾，是非对抗性的矛盾；敌我矛盾是对抗性矛盾",
