    "stem": "1986年9月，党的十二届六中全会根据邓小平关于加强精神文明建设的思想，提出以经济建设为中心，坚定不移地进行经济体制改革，坚定不移地进行政治体制改革，坚定不移地加强精神文明建设，并且使这几个方面互相配合、互相促进，初步形成了我国社会主义现代化建设“三位一体”的总体布局。",
