    "stem": "毛泽东从中国改革开放和现代化的实际出发，不仅强调物质文明和精神文明两手抓，两手都要硬，而且还提出了一系列“两手抓”，包括：“一手抓建设，一手抓法治”“一手抓改革开放，一手抓惩治腐败”等，这一些列“两手抓”，坚持了辩证法的全面性，坚持了两点论和重点论的统一。",
