    "unit": 8,
    "type": "judge",
    "stem": "统筹兼顾是科学发展观的根本方法，深刻体现了唯物辩证法在发展问题上的科学运用，深刻揭示了实现科学发展、促进社会和谐的基本途径，是正确处理经济社会发展中重大关系的方针原则。",
